export const getProductsByDepartment = (dept = 'woman') => {
  if (dept === 'sale') {
    return Object.values(PRODUCTS).filter(p => p.onSale);
  }
  return Object.values(PRODUCTS).filter(p => p.department === dept);
};

export const getSaleProducts = () => {
  return Object.values(PRODUCTS).filter(p => p.onSale);
};
